@namespace sv_67039faab8c04900b1974b3d03d9fb56.Components.Pages.Apply

<div class="step-form">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea class="cover-letter-textarea" @bind="Text" @bind:event="oninput" maxlength="2000"
                  placeholder="Tell us why you're a great fit for this position..."></textarea>
        <div class="character-count @(Text.Length > 1800 ? "warning" : "")">
            @Text.Length / 2000 characters
        </div>
    </div>

    <div class="step-buttons">
        <button class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string Text { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(Text);
    }
}

@namespace sv_67039faab8c04900b1974b3d03d9fb56.Components.Pages.Apply
@using sv_67039faab8c04900b1974b3d03d9fb56.Components.Pages.Apply

<div class="step-form review-step">
    <h3>Review & Submit</h3>
    <p class="form-hint">Please review your application before submitting.</p>

    <div class="review-section">
        <div class="review-header">
            <h4>Personal Information</h4>
            <button class="btn-link" @onclick="() => OnEdit.InvokeAsync(0)">Edit</button>
        </div>
        <dl>
            <dt>Name</dt><dd>@FullName</dd>
            <dt>Email</dt><dd>@Email</dd>
            <dt>Phone</dt><dd>@Phone</dd>
            <dt>Address</dt><dd>@Address</dd>
        </dl>
    </div>

    <div class="review-section">
        <div class="review-header">
            <h4>Work History</h4>
            <button class="btn-link" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-entry">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <br />
                <span class="review-dates">@entry.StartDate.ToString("MMM yyyy") — @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")</span>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p class="review-description">@entry.Description</p>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h4>References</h4>
            <button class="btn-link" @onclick="() => OnEdit.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var r in References)
        {
            <div class="review-entry">
                <strong>@r.Name</strong> — @r.Relationship
                <br />
                <span>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")</span>
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h4>Cover Letter</h4>
            <button class="btn-link" @onclick="() => OnEdit.InvokeAsync(3)">Edit</button>
        </div>
        <p class="review-cover-letter">@CoverLetter</p>
    </div>

    <div class="step-buttons">
        <button class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn-primary btn-submit" @onclick="() => OnSubmit.InvokeAsync()" disabled="@IsSubmitting">
            @(IsSubmitting ? "Submitting..." : "Submit Application")
        </button>
    </div>
