@page "/apply"
@namespace sv_67039faab8c04900b1974b3d03d9fb56.Components.Pages.Apply
@using sv_67039faab8c04900b1974b3d03d9fb56.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h2>Job Application</h2>

    @if (SubmittedId.HasValue)
    {
        <div class="submission-confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h3>Application Submitted!</h3>
            <p>Your application has been received successfully.</p>
            <p class="application-id">Application ID: <strong>@SubmittedId.Value</strong></p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="CurrentStep" OnStepSelected="GoToStep" />

        @switch (CurrentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@PersonalFullName"
                                  Email="@PersonalEmail"
                                  Phone="@PersonalPhone"
                                  Address="@PersonalAddress"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalNext" />
                break;
            case 1:
                <WorkHistoryStep Entries="WorkEntries" OnNext="HandleWorkNext" OnBack="GoBack" />
                break;
            case 2:
                <ReferencesStep References="ReferenceEntries" OnNext="HandleReferencesNext" OnBack="GoBack" />
                break;
            case 3:
                <CoverLetterStep Text="@CoverLetterText" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
                break;
            case 4:
                <ReviewStep FullName="@PersonalFullName"
                            Email="@PersonalEmail"
                            Phone="@PersonalPhone"
                            Address="@PersonalAddress"
                            WorkEntries="WorkEntries"
                            References="ReferenceEntries"
                            CoverLetter="@CoverLetterText"
                            IsSubmitting="IsSubmitting"
                            OnBack="GoBack"
                            OnSubmit="HandleSubmit"
                            OnEdit="GoToStep" />
                break;
        }
    }
</div>

@code {
    private int CurrentStep = 0;
    private int? SubmittedId;
    private bool IsSubmitting;

    // Personal Info state
    private string PersonalFullName = "";
    private string PersonalEmail = "";
    private string PersonalPhone = "";
    private string PersonalAddress = "";

    // Work History state
    private List<WorkHistoryStep.WorkEntryModel> WorkEntries = new() { new() };

    // References state
    private List<ReferencesStep.ReferenceModel> ReferenceEntries = new() { new(), new() };

    // Cover Letter state
    private string CoverLetterText = "";

    private void GoToStep(int step)
    {
        CurrentStep = step;
    }

    private void GoBack()
    {
        if (CurrentStep > 0) CurrentStep--;
    }

    private void HandlePersonalNext((string FullName, string Email, string Phone, string Address) data)
    {
        PersonalFullName = data.FullName;
        PersonalEmail = data.Email;
        PersonalPhone = data.Phone;
        PersonalAddress = data.Address;
        CurrentStep = 1;
    }

    private void HandleWorkNext(List<WorkHistoryStep.WorkEntryModel> entries)
    {
        WorkEntries = entries;
        CurrentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> references)
    {
        ReferenceEntries = references;
        CurrentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        CoverLetterText = text;
        CurrentStep = 4;
    }

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        StateHasChanged();

        var application = new JobApplication(
            new PersonalInfo(PersonalFullName, PersonalEmail, PersonalPhone, PersonalAddress),
            new WorkHistory(WorkEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            ReferenceEntries.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            CoverLetterText
        );

        SubmittedId = await ApplicationService.SubmitApplicationAsync(application);
        IsSubmitting = false;
    }
}

.application-container {
    max-width: 800px;
    margin: 2rem auto;
    padding: 2rem;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.application-container h2 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.85rem;
    border: 2px solid #ddd;
    background: #fff;
    color: #999;
    transition: all 0.2s;
}

.step.active .step-circle {
    border-color: #4361ee;
    background: #4361ee;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #2ecc71;
    background: #2ecc71;
    color: #fff;
}

.step.future .step-circle {
    opacity: 0.5;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    color: #666;
    text-align: center;
    white-space: nowrap;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ecc71;
}

.step.future .step-label {
