    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.application-container h2 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.85rem;
    border: 2px solid #ddd;
    background: #fff;
    color: #999;
    transition: all 0.2s;
}

.step.active .step-circle {
    border-color: #4361ee;
    background: #4361ee;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #2ecc71;
    background: #2ecc71;
    color: #fff;
}

.step.future .step-circle {
    opacity: 0.5;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    color: #666;
    text-align: center;
    white-space: nowrap;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ecc71;
}

.step.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ddd;
    margin: 0 0.5rem;
    margin-bottom: 1.2rem;
    max-width: 60px;
}

.step-connector.completed {
    background: #2ecc71;
}

/* Form Styles */
.step-form {
    background: #fff;
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 2rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.04);
}

.step-form h3 {
    margin-top: 0;
    margin-bottom: 0.5rem;
    color: #1a1a2e;
}

.form-hint {
    color: #666;
    margin-bottom: 1.5rem;
}

.form-group {
    margin-bottom: 1.2rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ddd;
    border-radius: 4px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.1);
}

.form-group textarea {
    min-height: 80px;
    resize: vertical;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal !important;
    margin-top: 0.4rem;
    font-size: 0.85rem;
    color: #555;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #eee;
}

.btn-primary {
    background: #4361ee;
    color: #fff;
    border: none;
    padding: 0.7rem 1.8rem;
    border-radius: 4px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary:hover:not(:disabled) {
    background: #3451d1;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-outline {
    background: transparent;
    color: #4361ee;
    border: 1px solid #4361ee;
    padding: 0.7rem 1.8rem;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-outline:hover {
    background: #f0f3ff;
}

.btn-secondary {
    background: #f0f3ff;
    color: #4361ee;
    border: 1px solid #d0d9ff;
    padding: 0.5rem 1.2rem;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    margin-top: 1rem;
    transition: all 0.2s;
}

.btn-secondary:hover {
    background: #e0e7ff;
}

.btn-danger-sm {
    background: #fee;
    color: #e74c3c;
    border: 1px solid #fcc;
    padding: 0.3rem 0.8rem;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
}

.btn-danger-sm:hover {
    background: #fdd;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.85rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #3451d1;
}

.btn-submit {
    padding: 0.8rem 2.5rem;
    font-size: 1rem;
}

/* Validation */
.validation-error {
    background: #fee;
    color: #c0392b;
    border: 1px solid #fcc;
    border-radius: 4px;
    padding: 0.7rem 1rem;
    margin-bottom: 1.2rem;
    font-size: 0.9rem;
}

/* Work Entry / Reference Form */
.work-entry-form,
.reference-form {
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    padding: 1.2rem;
    margin-bottom: 1rem;
    background: #fafbfc;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h4 {
    margin: 0;
    color: #333;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px !important;
    font-family: inherit;
}

.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.4rem;
}

.character-count.warning {
    color: #e67e22;
    font-weight: 500;
}

/* Review Step */
.review-step .review-section {
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    padding: 1.2rem;
    margin-bottom: 1rem;
    background: #fafbfc;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.8rem;
}

.review-header h4 {
    margin: 0;
    color: #1a1a2e;
}

.review-section dl {
    display: grid;
    grid-template-columns: 100px 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #555;
}

.review-section dd {
    margin: 0;
    color: #333;
}

.review-entry {
    padding: 0.6rem 0;
    border-bottom: 1px solid #eee;
}

.review-entry:last-child {
    border-bottom: none;
}

.review-dates {
    font-size: 0.85rem;
    color: #666;
}

.review-description {
    margin: 0.4rem 0 0;
    font-size: 0.9rem;
    color: #555;
}

.review-cover-letter {
    white-space: pre-wrap;
    color: #333;
    line-height: 1.6;
}

/* Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 2rem;
    background: #f0fff4;
    border: 1px solid #c6f6d5;
    border-radius: 8px;
}

.confirmation-icon {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background: #2ecc71;
    color: #fff;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1rem;
}

.submission-confirmation h3 {
    color: #2ecc71;
    margin-bottom: 0.5rem;
}

.application-id {
    font-size: 1.1rem;
    margin-top: 1rem;
    padding: 0.8rem;
    background: #fff;
    border-radius: 4px;
    display: inline-block;
}
