        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Company" @onchange="OnCompanyChanged" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Title" @onchange="OnTitleChanged" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChanged" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(EndDate?.ToString("yyyy-MM-dd"))" @onchange="OnEndDateChanged" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="OnIsCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Description" @onchange="OnDescriptionChanged" placeholder="Describe your responsibilities..."></textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = string.Empty;
    [Parameter] public string Title { get; set; } = string.Empty;
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = string.Empty;
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<(int Index, string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description)> OnChanged { get; set; }

    private Task HandleRemove() => OnRemove.InvokeAsync();

    private void OnCompanyChanged(ChangeEventArgs e)
    {
        Company = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void OnTitleChanged(ChangeEventArgs e)
    {
        Title = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            StartDate = date;
        NotifyChanged();
    }

    private void OnEndDateChanged(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        EndDate = string.IsNullOrEmpty(val) ? null : DateTime.TryParse(val, out var d) ? d : null;
        NotifyChanged();
    }

    private void OnIsCurrentChanged(ChangeEventArgs e)
    {
        IsCurrent = (bool)(e.Value ?? false);
        if (IsCurrent) EndDate = null;
        NotifyChanged();
    }

    private void OnDescriptionChanged(ChangeEventArgs e)
    {
        Description = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync((Index, Company, Title, StartDate, IsCurrent ? null : EndDate, Description));
    }
}

