@namespace sv_67039faab8c04900b1974b3d03d9fb56.Components.Pages.Apply

<div class="reference-form">
    <div class="entry-header">
        <h4>Reference @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button class="btn-danger-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Name" @onchange="e => { Name = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Relationship" @onchange="e => { Relationship = e.Value?.ToString() ?? ""; NotifyChanged(); }" placeholder="e.g., Former Manager" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Email" @onchange="e => { Email = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Phone" @onchange="e => { Phone = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = "";
    [Parameter] public string Relationship { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<(int Index, string Name, string Relationship, string Email, string Phone)> OnChanged { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync((Index, Name, Relationship, Email, Phone));
    }
}

