@namespace sv_67039faab8c04900b1974b3d03d9fb56.Components.Pages.Apply

<div class="reference-form">
    <div class="entry-header">
        <h4>Reference @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button class="btn-danger-sm" @onclick="HandleRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Name" @onchange="OnNameChanged" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Relationship" @onchange="OnRelationshipChanged" placeholder="e.g., Former Manager" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Email" @onchange="OnEmailChanged" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Phone" @onchange="OnPhoneChanged" />
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = string.Empty;
    [Parameter] public string Relationship { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<(int Index, string Name, string Relationship, string Email, string Phone)> OnChanged { get; set; }

    private Task HandleRemove() => OnRemove.InvokeAsync();

    private void OnNameChanged(ChangeEventArgs e)
    {
        Name = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void OnRelationshipChanged(ChangeEventArgs e)
    {
        Relationship = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void OnEmailChanged(ChangeEventArgs e)
    {
        Email = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void OnPhoneChanged(ChangeEventArgs e)
    {
        Phone = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync((Index, Name, Relationship, Email, Phone));
    }
}

